import{_ as n,o as i,c as a,ai as p}from"./chunks/framework.BxxKhjs3.js";const l="/pub-blog/assets/PixPin_2024-12-27_08-56-40.CbdbOUpC.gif",e="/pub-blog/assets/PixPin_2024-12-27_09-04-29.ht157kcI.gif",t="/pub-blog/assets/PixPin_2024-12-27_09-09-34.DW7pM5He.gif",h="/pub-blog/assets/PixPin_2024-12-27_09-22-38.C4vJck5e.gif",k="/pub-blog/assets/PixPin_2024-12-27_09-26-09.DQ8ptsO2.gif",y=JSON.parse('{"title":"HarmonyOS Next 弹窗系列教程（4）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（4）/HarmonyOS Next 弹窗系列教程（4）.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（4）/HarmonyOS Next 弹窗系列教程（4）.md","lastUpdated":1748912459000,"__rawMarkdown":"# HarmonyOS Next 弹窗系列教程（4）\\n\\n## 介绍\\n\\n本章主要介绍和用户点击关联更加密切的**菜单控制（Menu）** 和  **气泡提示（Popup）**\\n\\n它们出现显示弹窗出现的位置都是在用户点击屏幕的位置相关\\n\\n## 菜单控制（Menu）\\n\\nMenu是菜单接口，一般用于鼠标右键弹窗、点击弹窗等。具体用法请参考[菜单控制](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-universal-attributes-menu-V5)。\\n\\n使用[bindContextMenu](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-universal-attributes-menu-V5#bindcontextmenu12)并设置预览图，菜单弹出时有蒙层，此时为模态。\\n\\n使用[bindMenu](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-universal-attributes-menu-V5#bindmenu11)或bindContextMenu未设置预览图时，菜单弹出无蒙层，此时为非模态。\\n\\n\\n\\n### 基本用法\\n\\n在按钮或者元素上调用**bindMenu**，并且传入菜单内容即可\\n\\n![PixPin_2024-12-27_08-56-40](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%884%EF%BC%89.assets/PixPin_2024-12-27_08-56-40.gif)\\n\\n```tsx\\n@Entry\\n@Component\\nstruct Index {\\n  build() {\\n    Column() {\\n      Button(\'click for Menu\')\\n        .bindMenu([\\n          {\\n            value: \'Menu1\',\\n            action: () => {\\n              console.info(\'handle Menu1 select\')\\n            }\\n          }\\n        ])\\n    }.width(\'100%\').margin({ top: 5 })\\n  }\\n}\\n```\\n\\n### 自定义菜单内容\\n\\n如果想要个性化的自定义弹出的菜单内容，按照以下步骤进行即可\\n\\n1. 使用@Builder自定义要显示的内容\\n\\n   ```jsx\\n     // 子菜单\\n     @Builder\\n     SubMenu() {\\n       Menu() {\\n         MenuItem({ content: \\"复制\\", labelInfo: \\"Ctrl+C\\" })\\n         MenuItem({ content: \\"粘贴\\", labelInfo: \\"Ctrl+V\\" })\\n       }\\n     }\\n   \\n     // 主菜单\\n     @Builder\\n     MyMenu() {\\n       Menu() {\\n         MenuItem({ startIcon: $r(\\"app.media.foreground\\"), content: \\"菜单选项\\" })\\n         MenuItem({ startIcon: $r(\\"app.media.layered_image\\"), content: \\"菜单选项\\" }).enabled(false)\\n   \\n         MenuItemGroup({ header: \'小标题\' }) {\\n           MenuItem({ content: \\"菜单选项\\", builder: this.SubMenu })\\n   \\n         }\\n   \\n       }\\n     }\\n   \\n   ```\\n\\n   \\n\\n2. 使用bindMenu绑定显示的内容\\n\\n   ```jsx\\n       Button(\'click for Menu\')\\n         .bindMenu(this.MyMenu)\\n   ```\\n\\n\\n\\n\\n\\n\\n\\n**效果**：\\n\\n![PixPin_2024-12-27_09-04-29](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%884%EF%BC%89.assets/PixPin_2024-12-27_09-04-29.gif)\\n\\n\\n\\n### 右键或长按菜单\\n\\nMenu还支持创建右键/长按菜单\\n\\n1. 使用**bindContextMenu**来绑定菜单\\n2. 传入 **ResponseType.RightClick** 表示右键\\n3. 传入 **ResponseType.LongPress** 表示长按\\n\\n```jsx\\n  Button(\'click for Menu\')\\n    .bindContextMenu(this.MyMenu, ResponseType.LongPress)\\n```\\n\\n![PixPin_2024-12-27_09-09-34](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%884%EF%BC%89.assets/PixPin_2024-12-27_09-09-34.gif)\\n\\n\\n\\n\\n\\n## 气泡提示（Popup）\\n\\nopup属性可绑定在组件上显示气泡弹窗提示，设置弹窗内容、交互逻辑和显示状态。主要用于屏幕录制、信息弹出提醒等显示状态。\\n\\n气泡分为两种类型，一种是系统提供的气泡[PopupOptions](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-universal-attributes-popup-V5#popupoptions类型说明)，一种是开发者可以自定义的气泡[CustomPopupOptions](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-universal-attributes-popup-V5#custompopupoptions8类型说明)。\\n\\n### 基本用法\\n\\n1. 通过一个布尔值来设置汽贸的显示和隐藏\\n2. 通过message属性设置气泡的内容\\n\\n![PixPin_2024-12-27_09-22-38](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%884%EF%BC%89.assets/PixPin_2024-12-27_09-22-38.gif)\\n\\n```jsx\\n@Entry\\n@Component\\nstruct PopupExample {\\n  // 控制气泡显示隐藏\\n  @State handlePopup: boolean = false\\n\\n  build() {\\n    Column() {\\n      Button(\'PopupOptions\')\\n        .onClick(() => {\\n          this.handlePopup = !this.handlePopup\\n        })\\n        .bindPopup(this.handlePopup, {\\n          message: \'This is a popup with PopupOptions\',\\n        })\\n    }.width(\'100%\').padding({ top: 5 })\\n  }\\n}\\n```\\n\\n### 监听气泡的显示隐藏状态\\n\\n通过onStateChange参数为气泡添加状态变化的事件回调，可以判断当前气泡的显示状态。\\n\\n```jsx\\n@Entry\\n@Component\\nstruct PopupExample {\\n  @State handlePopup: boolean = false\\n\\n  build() {\\n    Column() {\\n      Button(\'PopupOptions\')\\n        .onClick(() => {\\n          this.handlePopup = !this.handlePopup\\n        })\\n        .bindPopup(this.handlePopup, {\\n          message: \'This is a popup with PopupOptions\',\\n          onStateChange: (e)=> { // 返回当前的气泡状态\\n            if (!e.isVisible) {\\n              this.handlePopup = false\\n            }\\n          }\\n        })\\n    }.width(\'100%\').padding({ top: 5 })\\n  }\\n}\\n```\\n\\n### 自定义气泡内容\\n\\n我们可以通**@Builder**自定义要显示的气泡的内容,然后通过**builder**属性进行调用\\n\\n![PixPin_2024-12-27_09-26-09](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%884%EF%BC%89.assets/PixPin_2024-12-27_09-26-09.gif)\\n\\n```jsx\\n@Entry\\n@Component\\nstruct Index {\\n  @State customPopup: boolean = false\\n\\n  // popup构造器定义弹框内容\\n  @Builder\\n  popupBuilder() {\\n    Row() {\\n      Button(\\"1\\")\\n      Button(\\"2\\")\\n    }\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(\'CustomPopupOptions\')\\n        .position({ x: 100, y: 200 })\\n        .onClick(() => {\\n          this.customPopup = !this.customPopup\\n        })\\n        .bindPopup(this.customPopup, {\\n          builder: this.popupBuilder, // 气泡的内容\\n          placement: Placement.Bottom, // 气泡的弹出位置\\n          popupColor: Color.Pink, // 气泡的背景色\\n        })\\n    }\\n    .height(\'100%\')\\n  }\\n}\\n```\\n\\n### 参考链接\\n\\n[最后，想要更多了解气泡不同的用法，可以参考官方链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-popup-and-menu-components-popup-V5#%E6%B0%94%E6%B3%A1%E6%A0%B7%E5%BC%8F)\\n\\n\\n\\n"}'),r={name:"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（4）/HarmonyOS Next 弹窗系列教程（4）.md"};function E(d,s,o,u,c,g){return i(),a("div",null,[...s[0]||(s[0]=[p("",38)])])}const m=n(r,[["render",E]]);export{y as __pageData,m as default};
